const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const response = $input.first().json;
const workItems = Array.isArray(response.results) ? response.results : [];

const priorityOrder = { urgent: 0, high: 1, medium: 2, low: 3, none: 4 };
const candidates = workItems
  .filter((item) => !item.completed_at)
  .map((item) => {
    const description = (item.description_stripped ?? '').replace(/\s+/g, ' ').trim();
    const hasAcceptance = /Acceptance Criteria/i.test(description);
    const hasRepoMetadata = /Repo Metadata/i.test(description);
    return {
      id: item.id,
      title: item.name,
      priority: item.priority ?? 'none',
      updatedAt: item.updated_at,
      description,
      needsExpansion: description.length < 260 || !hasAcceptance || !hasRepoMetadata,
    };
  })
  .filter((item) => item.needsExpansion)
  .sort((left, right) => {
    const leftPriority = priorityOrder[left.priority] ?? 99;
    const rightPriority = priorityOrder[right.priority] ?? 99;
    if (leftPriority !== rightPriority) return leftPriority - rightPriority;
    return String(right.updatedAt).localeCompare(String(left.updatedAt));
  })
  .slice(0, 5);

const dateStamp = new Date().toISOString().slice(0, 10);
const reportRelativePath = `plane-task-expansions/${dateStamp}.md`;

if (candidates.length === 0) {
  const content = [
    '# Plane Task Expansion Assistant',
    '',
    `Generated: ${new Date().toISOString()}`,
    '',
    'No candidate tasks needed expansion today.',
  ].join('\n');

  await fetch(`${runnerBase}/reports/write`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
    },
    body: JSON.stringify({ relativePath: reportRelativePath, content }),
  });

  return [{ json: { generatedAt: new Date().toISOString(), candidateCount: 0, reportRelativePath, candidates: [] } }];
}

const prompt = [
  'You are helping expand shallow Plane tasks for the Wazaker project.',
  'For each task below, produce a markdown section with: Why This Matters, Expanded Description, Acceptance Criteria, Risks, Suggested Next Step.',
  'Do not invent implementation details that conflict with the existing description.',
  'Prefer project-operations framing over product-runtime speculation.',
  '',
  'Tasks:',
  JSON.stringify(candidates, null, 2),
].join('\n');

let expansion = '';
let expansionSource = 'ollama';
try {
  const ollamaResponse = await fetch('http://host.docker.internal:11434/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'qwen3:8b', prompt, stream: false }),
  });
  if (!ollamaResponse.ok) {
    const body = await ollamaResponse.text();
    throw new Error(`Ollama request failed: ${ollamaResponse.status} ${body}`);
  }
  const ollamaJson = await ollamaResponse.json();
  expansion = (ollamaJson.response ?? '').trim();
} catch (error) {
  expansionSource = 'fallback';
  expansion = candidates.map((item, index) => [
    `## Candidate ${index + 1}: ${item.title}`,
    '',
    '### Why This Matters',
    '',
    `This work item still needs expansion before implementation can proceed safely. Priority: ${item.priority}.`,
    '',
    '### Expanded Description',
    '',
    item.description || 'Description was empty.',
    '',
    '### Acceptance Criteria',
    '',
    '- Confirm the task has explicit acceptance criteria.',
    '- Add repo metadata if it is missing.',
    '- Clarify the expected deliverable before implementation starts.',
    '',
    '### Risks',
    '',
    `Fallback expansion generated because the Ollama request was unavailable: ${error instanceof Error ? error.message : String(error)}`,
    '',
    '### Suggested Next Step',
    '',
    '- Review this task manually and expand it in Plane before assigning implementation.',
  ].join('\n')).join('\n\n');
}

const content = [
  '# Plane Task Expansion Assistant',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Candidates: ${candidates.length}`,
  `Expansion source: ${expansionSource}`,
  '',
  expansion || 'No expansion generated.',
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
  },
  body: JSON.stringify({ relativePath: reportRelativePath, content }),
});
if (!writeResponse.ok) {
  const body = await writeResponse.text();
  throw new Error(`Runner report write failed: ${writeResponse.status} ${body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    candidateCount: candidates.length,
    candidates,
    expansion,
    expansionSource,
    reportRelativePath,
  },
}];
